import { spawn } from 'node:child_process'
import { tmpdir } from 'node:os'
import path from 'node:path'
import fs from 'node:fs'

import type { Config, ConfigStack } from './index.ts'
import type { Spec } from '../resource.ts'

export type Cx = { config: Config; temp: string }

export const createContext = (config: Config): Cx => ({ config, temp: fs.mkdtempSync(path.join(tmpdir(), 'ship-')) })

export const resolvePath = async (ctx: Cx, stack: ConfigStack): Promise<string> => {
  if (typeof stack === 'string') return stack
  if (typeof stack === 'function') return storeScratch(ctx, stack())
  return storeScratch(ctx, stack)
}

const storeScratch = async (ctx: Cx, stack: Promise<Spec> | Spec) => {
  const st = await stack
  const scratch = path.join(ctx.temp, `${st.name}.json`)
  await fs.promises.writeFile(scratch, JSON.stringify(st, null, 2))
  return scratch
}

export type ShellOptions = { bin: string; env: Record<string, string | undefined>; args: string[] }
export const execute = (ctx: Cx, config: ShellOptions): Promise<number> => {
  return new Promise<number>((done, fail) => {
    const child = spawn(config.bin, config.args, { stdio: 'inherit', env: config.env })
    child.on('error', fail)
    child.on('close', (code, signal) => done(code ?? (signal ? 1 : 0)))
  }).finally(() => cleanScratch(ctx))
}

export const cleanScratch = (ctx: Cx) => {
  for (const file of fs.readdirSync(ctx.temp)) {
    fs.rmSync(path.join(ctx.temp, file), { recursive: true, force: true })
  }
}
